async def act(page):
    # Wait for the page to be fully loaded
    await page.wait_for_load_state('networkidle')

    # Select all group elements with name='Labels' that contain a link with name='enhancement'
    enhancement_groups = page.get_by_role('group', name='Labels').filter(
        has=page.get_by_role('link', name='enhancement')
    )

    # Get the count of such groups
    count = await enhancement_groups.count()

    # Collect the issue titles
    issue_titles = []
    for i in range(count):
        group = enhancement_groups.nth(i)
        # Use evaluate to get the second preceding sibling link (the issue title link)
        title_link = await group.evaluate('''node => {
            let prev = node.previousElementSibling;
            if (prev) {
                let titleLink = prev.previousElementSibling;
                if (titleLink && titleLink.tagName.toLowerCase() === 'a') {
                    return titleLink.textContent;
                }
            }
            return null;
        }''')
        if title_link:
            issue_titles.append(title_link)

    # Print the list of opened issues requesting new features
    for title in issue_titles:
        print(title)

